function ridgeR46(rows,context){
 const columns=["intercept",...Array.from({length:10},(_,i)=>"age"+(i+2)),"progress",...(context?["recent","giveback"]:[])];
 const xs=rows.map(r=>[1,...Array.from({length:10},(_,i)=>+(r.age===i+2)),r.progress,...(context?[r.recent,r.giveback]:[])]);
 const groups=new Map;for(const r of rows)groups.set(r.origin,(groups.get(r.origin)||0)+1);
 const weights=rows.map(r=>rows.length/(groups.size*groups.get(r.origin))),sw=weights.reduce((s,v)=>s+v,0),p=columns.length;
 const means=Array(p).fill(0),scales=Array(p).fill(1),constant=Array(p).fill(false);
 for(let j=1;j<p;j++){const vals=xs.map(x=>x[j]);constant[j]=vals.every(v=>v===vals[0]);means[j]=constant[j]?vals[0]:vals.reduce((s,v,i)=>s+weights[i]*v,0)/sw;if(!constant[j])scales[j]=Math.sqrt(vals.reduce((s,v,i)=>s+weights[i]*(v-means[j])**2,0)/sw);if(scales[j]===0)scales[j]=1;}
 const z=xs.map(x=>x.map((v,j)=>j===0?1:constant[j]?0:(v-means[j])/scales[j]));
 const A=Array.from({length:p},()=>Array(p).fill(0)),b=Array(p).fill(0);
 for(let i=0;i<rows.length;i++)for(let j=0;j<p;j++){b[j]+=weights[i]*z[i][j]*rows[i].y;for(let k=0;k<p;k++)A[j][k]+=weights[i]*z[i][j]*z[i][k];}
 for(let j=1;j<p;j++)A[j][j]+=1;
 for(let j=0;j<p;j++){let pivot=j;for(let i=j+1;i<p;i++)if(Math.abs(A[i][j])>Math.abs(A[pivot][j]))pivot=i;if(Math.abs(A[pivot][j])<1e-12)throw Error("singular ridge");[A[j],A[pivot]]=[A[pivot],A[j]];[b[j],b[pivot]]=[b[pivot],b[j]];const d=A[j][j];for(let k=j;k<p;k++)A[j][k]/=d;b[j]/=d;for(let i=0;i<p;i++)if(i!==j){const f=A[i][j];for(let k=j;k<p;k++)A[i][k]-=f*A[j][k];b[i]-=f*b[j];}}
 return {columns,means,scales,constant,beta:b,rows:rows.length,origin_days:groups.size,weight_sum:sw};
}
